export interface BulkCancelEpicTasksInput {
  project_id: string;
  epic_id: string;
  reason?: string;
  force?: boolean;
}

export interface BulkCancelEpicTasksResult {
  cancelled_task_ids: string[];
  skipped: Array<{ task_id: string; reason: string }>;
  unblocked_task_ids: string[];
}

export function bulkCancelEpicTasks(
  db: DatabaseInstance,
  input: BulkCancelEpicTasksInput,
): BulkCancelEpicTasksResult {
  const project = requireProject(db, input.project_id);
  const epic = requireEpic(db, project.id, input.epic_id);

  const candidates = db
    .prepare(`SELECT id FROM tasks WHERE epic_id = ? AND status NOT IN ('done', 'cancelled')`)
    .all(epic.id) as Array<{ id: string }>;

  const cancelledTaskIds: string[] = [];
  const skipped: Array<{ task_id: string; reason: string }> = [];
  const unblockedTaskIds = new Set<string>();

  for (const { id: taskId } of candidates) {
    try {
      const result = cancelTask(db, { task_id: taskId, reason: input.reason, force: input.force });
      cancelledTaskIds.push(taskId);
      result.unblocked_task_ids.forEach((id) => unblockedTaskIds.add(id));
    } catch (error) {
      if (error instanceof TaskConflictError || error instanceof Error) {
        skipped.push({ task_id: taskId, reason: error.message });
        continue;
      }
      throw error;
    }
